Map c = j.context instanceof Map ? j.context : new HashMap();
Map x = j.extra instanceof Map ? j.extra : new HashMap();
Object tid = x.trace_id != null ? x.trace_id : c.trace_id;
if (tid instanceof String) { ctx.trace = ['id': tid]; }
if (c.exception instanceof Map) {
  Map e = c.exception;
  Map err = new HashMap();
  if (e['class'] != null) { err.type = e['class']; }
  if (e.message != null) { err.message = e.message; }
  if (e.trace instanceof List) {
    StringBuilder sb = new StringBuilder();
    for (def l : e.trace) { if (sb.length() > 0) { sb.append((char) 10); } sb.append(l); }
    err.stack_trace = sb.toString();
  } else if (e.trace != null) {
    err.stack_trace = e.trace.toString();
  }
  ctx.error = err;
}
Map rest = new HashMap(c);
rest.remove('trace_id');
rest.remove('exception');
Map xrest = new HashMap(x);
xrest.remove('trace_id');
Map app = new HashMap();
if (!rest.isEmpty()) { app.context = rest; }
if (!xrest.isEmpty()) { app.extra = xrest; }
if (!app.isEmpty()) { ctx.app = app; }

Map j = ctx._j;
Map r = j.request instanceof Map ? j.request : new HashMap();
Map http = new HashMap();
if (r.method != null) { http.request = ['method': r.method]; }
if (j.status instanceof Number) { http.response = ['status_code': j.status]; }
if (!http.isEmpty()) { ctx.http = http; }
if (r.uri instanceof String) {
  String u = r.uri;
  int q = u.indexOf('?');
  ctx.url = ['original': u, 'path': q >= 0 ? u.substring(0, q) : u];
}
if (j.duration instanceof Number) {
  if (ctx.event == null) { ctx.event = new HashMap(); }
  ctx.event.duration = Math.round(j.duration.doubleValue() * 1000000000.0);
}
if (j.resp_headers instanceof Map) {
  def h = j.resp_headers['X-Trace-Id'];
  if (h instanceof List && h.size() > 0) { ctx.trace = ['id': h[0]]; }
  else if (h instanceof String) { ctx.trace = ['id': h]; }
}
